cat > src/notes.js <<'EOF'
// Pure note-list operations. Every function returns a new frozen list; inputs are never mutated.

export function createNote(id, text, createdAt) {
  return Object.freeze({ id, text, pinned: false, createdAt });
}

function requireNote(notes, id) {
  if (!notes.some((note) => note.id === id)) {
    throw new RangeError(`no note with id ${id}`);
  }
}

export function addNote(notes, note) {
  if (notes.some((existing) => existing.id === note.id)) {
    throw new RangeError(`a note with id ${note.id} already exists`);
  }
  return Object.freeze([...notes, note]);
}

export function updateText(notes, id, text) {
  requireNote(notes, id);
  return Object.freeze(
    notes.map((note) => (note.id === id ? Object.freeze({ ...note, text }) : note)),
  );
}

export function togglePin(notes, id) {
  requireNote(notes, id);
  return Object.freeze(
    notes.map((note) => (note.id === id ? Object.freeze({ ...note, pinned: !note.pinned }) : note)),
  );
}

export function removeNote(notes, id) {
  requireNote(notes, id);
  return Object.freeze(notes.filter((note) => note.id !== id));
}

function compareForDisplay(a, b) {
  if (a.pinned !== b.pinned) {
    return Number(b.pinned) - Number(a.pinned);
  }
  return a.createdAt - b.createdAt;
}

/** Pinned notes first, then oldest first. */
export function displayOrder(notes) {
  return Object.freeze([...notes].sort(compareForDisplay));
}
EOF
cat > src/storage.js <<'EOF'
// Reading and writing the notes in a Storage-like object (getItem/setItem/removeItem).
// No DOM access: the caller passes the storage in.

export const STORAGE_FORMAT_VERSION = 1;

export class UnreadableNotesError extends Error {
  constructor(message, raw, options) {
    super(message, options);
    this.name = "UnreadableNotesError";
    this.raw = raw;
  }
}

function parseJson(raw) {
  // Boundary (declared in .shockharness.toml): one JSON.parse of stored text.
  try {
    return JSON.parse(raw);
  } catch (err) {
    if (!(err instanceof SyntaxError)) throw err;
    throw new UnreadableNotesError(`stored notes are not valid JSON: ${err.message}`, raw, {
      cause: err,
    });
  }
}

function isPlainObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNote(value) {
  return (
    isPlainObject(value) &&
    typeof value.id === "string" &&
    typeof value.text === "string" &&
    typeof value.pinned === "boolean" &&
    Number.isFinite(value.createdAt)
  );
}

/** Parse stored text into a frozen note list; throws UnreadableNotesError on any defect. */
export function parseNotes(raw) {
  const data = parseJson(raw);
  if (!isPlainObject(data) || data.version !== STORAGE_FORMAT_VERSION) {
    throw new UnreadableNotesError(
      `stored notes do not have format version ${STORAGE_FORMAT_VERSION}`,
      raw,
    );
  }
  if (!Array.isArray(data.notes) || !data.notes.every(isNote)) {
    throw new UnreadableNotesError("stored notes contain an entry that is not a note", raw);
  }
  const ids = new Set(data.notes.map((note) => note.id));
  if (ids.size !== data.notes.length) {
    throw new UnreadableNotesError("stored notes contain duplicate ids", raw);
  }
  return Object.freeze(
    data.notes.map((note) =>
      Object.freeze({ id: note.id, text: note.text, pinned: note.pinned, createdAt: note.createdAt }),
    ),
  );
}

export function serializeNotes(notes) {
  return JSON.stringify({ version: STORAGE_FORMAT_VERSION, notes });
}

/** Nothing stored yet means an empty board; stored text that cannot be read throws. */
export function readNotes(storage, key) {
  const raw = storage.getItem(key);
  if (raw === null) {
    return Object.freeze([]);
  }
  return parseNotes(raw);
}

export function writeNotes(storage, key, notes) {
  storage.setItem(key, serializeNotes(notes));
}
EOF
cat > src/load.js <<'EOF'
import { readNotes, UnreadableNotesError } from "./storage.js";

/**
 * Load the board. Unreadable stored data is never dropped: it is moved to a
 * quarantine key (named with `now`) and the result carries a message for the user.
 * keys: { notes, quarantinePrefix }.
 */
export function loadBoard(storage, keys, now) {
  let notes;
  // Boundary (declared in .shockharness.toml): one read of stored notes.
  try {
    notes = readNotes(storage, keys.notes);
  } catch (err) {
    if (!(err instanceof UnreadableNotesError)) throw err;
    return quarantine(storage, keys, now, err);
  }
  return Object.freeze({ notes, problem: null });
}

function quarantine(storage, keys, now, error) {
  const quarantineKey = `${keys.quarantinePrefix}${now}`;
  storage.setItem(quarantineKey, error.raw);
  storage.removeItem(keys.notes);
  const problem =
    `Saved notes could not be read (${error.message}). ` +
    `Starting with an empty board; the old data was kept in localStorage under "${quarantineKey}".`;
  return Object.freeze({ notes: Object.freeze([]), problem });
}
EOF
cat > src/edit-mode.js <<'EOF'
// Edit-mode decisions, free of the DOM. The caller describes what was pressed;
// these functions say what the board should do.

export const NOT_EDITING = null;

export const Action = Object.freeze({
  IGNORE: "ignore",
  SAVE: "save",
  CANCEL: "cancel",
  ENTER: "enter",
});

/**
 * A pointer press anywhere on the page.
 * press: { noteId: string | null (the note under the pointer), inOverlay: boolean (modal or toast) }
 */
export function decidePress(editingId, press) {
  if (editingId === NOT_EDITING || press.inOverlay) {
    return Action.IGNORE;
  }
  if (press.noteId === editingId) {
    return Action.IGNORE;
  }
  return Action.SAVE;
}

/** A key press. key: { key: string, inOverlay: boolean } */
export function decideKey(editingId, key) {
  if (key.key !== "Escape" || key.inOverlay || editingId === NOT_EDITING) {
    return Action.IGNORE;
  }
  return Action.CANCEL;
}

/** A click on a note's body (not its toolbar). */
export function decideNoteClick(editingId, noteId) {
  if (editingId === noteId) {
    return Action.IGNORE;
  }
  return Action.ENTER;
}
EOF
cat > src/config.js <<'EOF'
/** Toast duration from configuration text (a data attribute); must be a positive integer of ms. */
export function parseToastDurationMs(text) {
  if (typeof text !== "string" || !/^\d+$/.test(text)) {
    throw new TypeError(`toast duration must be a whole number of milliseconds, got ${text}`);
  }
  const duration = Number(text);
  if (duration <= 0) {
    throw new RangeError(`toast duration must be positive, got ${duration}`);
  }
  return duration;
}
